/**
 * PhysicsRayshoot - Hitscan weapon system for the physics engine
 *
 * Provides instant raycast-based shooting (hitscan) from either camera position
 * or body positions. Uses three-mesh-bvh for efficient ray-mesh intersection.
 * Attached as a singleton to Physics as `physics.rayshoot`.
 *
 * **Usage**
 *
 * ```js
 * import { Physics } from '@three-blocks/pro';
 *
 * const physics = new Physics();
 * await physics.init();
 *
 * // Fire from camera (crosshair) - most common for FPS games
 * physics.rayshoot.fireFromCamera({
 *   shooterIndex: 0,
 *   shooterType: 'dynamic',
 *   maxDistance: 100,
 * });
 *
 * // Fire from a specific body position/direction
 * physics.rayshoot.fire(npcIndex, {
 *   bodyType: 'kinematic',
 *   direction: [0, 0, 1],
 *   maxDistance: 100,
 * });
 *
 * // Listen for hits on a body
 * physics.on('kinematic_hit_5', (hitData) => {
 *   console.log('Body 5 was hit!', hitData);
 *   // hitData: { shooterIndex, shooterType, hitPoint, hitNormal, distance, instanceIdx }
 * });
 * ```
 *
 * **Terminology**
 *
 * | Term | Definition |
 * |------|------------|
 * | Hitscan | Instant raycast weapon (no travel time) |
 * | Shooter | Body that fires the raycast |
 * | Target | Body that receives the hit |
 * | Piercing | Ray passes through multiple targets |
 *
 * @class PhysicsRayshoot
 * @short Hitscan weapon system for instant raycast-based shooting
 * @category Core
 * @private
 * @tags Raycast, Hitscan, Weapons, BVH
 *
 * @see {@link Physics} - Main physics API that exposes this as `physics.rayshoot`
 */
export class PhysicsRayshoot {
    /**
     * Create a PhysicsRayshoot instance.
     * @param {Object} sharedViews - Shared buffer views
     * @param {Float32Array} sharedViews.rayshoot - Rayshoot request buffer
     * @param {ArrayOfBufferBackedObjects} sharedViews.dynamic - Dynamic bodies buffer
     * @param {ArrayOfBufferBackedObjects} sharedViews.kinematic - Kinematic bodies buffer
     */
    constructor(sharedViews: {
        rayshoot: Float32Array;
        dynamic: ArrayOfBufferBackedObjects;
        kinematic: ArrayOfBufferBackedObjects;
    });
    _sharedRayshoot: Float32Array<ArrayBufferLike>;
    _sharedDynamic: ArrayOfBufferBackedObjects;
    _sharedKinematic: ArrayOfBufferBackedObjects;
    /**
     * Fire a hitscan from a body's position in a specified direction.
     *
     * @param {number} shooterIndex - Index of the body firing the shot
     * @param {Object} options - Fire options
     * @param {string} [options.bodyType='dynamic'] - Body type ('dynamic' or 'kinematic')
     * @param {number[]} options.direction - Fire direction as [x, y, z]
     * @param {number[]} [options.origin] - Override origin position [x, y, z], defaults to body position
     * @param {number} [options.maxDistance=1000] - Maximum raycast distance
     * @param {boolean} [options.piercing=false] - If true, ray passes through all targets
     *
     * @example
     * ```js
     * // NPC fires forward
     * physics.rayshoot.fire(npcIndex, {
     *   bodyType: 'kinematic',
     *   direction: [0, 0, 1],
     *   maxDistance: 50,
     * });
     *
     * // Player fires with custom origin (e.g., gun muzzle)
     * physics.rayshoot.fire(0, {
     *   bodyType: 'dynamic',
     *   direction: forwardVector,
     *   origin: muzzlePosition,
     * });
     * ```
     */
    fire(shooterIndex: number, options?: {
        bodyType?: string;
        direction: number[];
        origin?: number[];
        maxDistance?: number;
        piercing?: boolean;
    }): void;
    /**
     * Fire a hitscan from the camera center (crosshair).
     * This is the most common firing method for FPS games.
     *
     * @param {Object} [options] - Fire options
     * @param {number} [options.shooterIndex=0] - Index of the body considered the shooter
     * @param {string} [options.shooterType='dynamic'] - Shooter body type ('dynamic' or 'kinematic')
     * @param {number} [options.maxDistance=1000] - Maximum raycast distance
     * @param {boolean} [options.piercing=false] - If true, ray passes through all targets
     *
     * @example
     * ```js
     * // Player shoots from crosshair
     * physics.rayshoot.fireFromCamera({
     *   shooterIndex: 0,
     *   shooterType: 'dynamic',
     *   maxDistance: 100,
     * });
     *
     * // Piercing shot (sniper rifle)
     * physics.rayshoot.fireFromCamera({
     *   maxDistance: 500,
     *   piercing: true,
     * });
     * ```
     */
    fireFromCamera(options?: {
        shooterIndex?: number;
        shooterType?: string;
        maxDistance?: number;
        piercing?: boolean;
    }): void;
}
